package dev.rajeev.shortener.web;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class ApiIntegrationTest {

    static TestServer server;

    @BeforeAll
    static void start() {
        server = new TestServer();
    }

    @AfterAll
    static void stop() {
        server.close();
    }

    @Test
    void postCreatesALinkAndReturns201() {
        TestServer.Resp r = server.post("/api/links", "{\"url\":\"https://example.com/a\"}");
        assertEquals(201, r.status());
        Map<String, Object> body = server.json(r);
        String code = (String) body.get("code");
        assertTrue(code.matches("^[0-9A-Za-z]{8}$"), code); // 8 chars since the guessability fix (62^8 keys)
        assertEquals("http://short.test/" + code, body.get("shortUrl"));
        assertEquals("https://example.com/a", body.get("targetUrl"));
        assertEquals(false, body.get("custom"));
        assertNotNull(r.header("X-Request-Id"));
    }

    @Test
    void echoesACallerSuppliedRequestIdForCorrelation() {
        TestServer.Resp r = server.get("/actuator/health/liveness", "X-Request-Id", "corr-123");
        assertEquals("corr-123", r.header("X-Request-Id"));
    }

    @Test
    void redirectsWith302AndNoStore() {
        String code = server.create("https://example.com/r");
        TestServer.Resp r = server.get("/" + code, "User-Agent", "curl/8.0");
        assertEquals(302, r.status());
        assertEquals("https://example.com/r", r.header("Location"));
        assertEquals("no-store", r.header("Cache-Control"));
    }

    @Test
    void statsReflectClicks() {
        String code = server.create("https://example.com/s");
        for (int i = 0; i < 3; i++) server.get("/" + code, "Referer", "https://t.co/x", "User-Agent", "curl/8");
        TestServer.Resp r = server.get("/api/links/" + code + "/stats?topN=2");
        assertEquals(200, r.status());
        Map<String, Object> stats = server.json(r);
        assertEquals(3, stats.get("totalClicks"));
        assertEquals(List.of(Map.of("referrer", "t.co", "clicks", 3)), stats.get("topReferrers"));
        assertEquals(List.of(Map.of("userAgent", "curl", "clicks", 3)), stats.get("topUserAgents"));
        assertEquals(1, ((List<?>) stats.get("clicksByDay")).size());
        assertNotNull(stats.get("lastClickAt"));
    }

    @Test
    void supportsCustomAliasesAndRejectsCollisionsWith409() {
        TestServer.Resp a = server.post("/api/links", "{\"url\":\"https://example.com\",\"customAlias\":\"launch-2026\"}");
        assertEquals(201, a.status());
        assertEquals("launch-2026", server.json(a).get("code"));
        TestServer.Resp b = server.post("/api/links", "{\"url\":\"https://example.org\",\"customAlias\":\"launch-2026\"}");
        assertEquals(409, b.status());
        assertEquals("ALIAS_TAKEN", server.json(b).get("error"));
    }

    @Test
    void rejectsReservedAliasesWith422() {
        TestServer.Resp r = server.post("/api/links", "{\"url\":\"https://example.com\",\"customAlias\":\"health\"}");
        assertEquals(422, r.status());
        assertEquals("ALIAS_RESERVED", server.json(r).get("error"));
    }

    @ParameterizedTest
    @CsvSource({
        "javascript:alert(1), 422, URL_NOT_ALLOWED",
        "http://localhost:3000/x, 422, URL_NOT_ALLOWED",
        "http://169.254.169.254/, 422, URL_NOT_ALLOWED",
        "https://short.test/abc, 422, URL_NOT_ALLOWED",
        "not-a-url, 400, INVALID_URL"
    })
    void rejectsDisallowedUrls(String url, int status, String error) {
        TestServer.Resp r = server.post("/api/links", "{\"url\":\"" + url + "\"}");
        assertEquals(status, r.status(), url);
        assertEquals(error, server.json(r).get("error"));
    }

    @Test
    void returns400ValidationForAMalformedBody() {
        assertEquals("VALIDATION", server.json(server.post("/api/links", "{\"nope\":1}")).get("error"));
        TestServer.Resp garbage = server.post("/api/links", "{not json");
        assertEquals(400, garbage.status());
        assertEquals("VALIDATION", server.json(garbage).get("error"));
        TestServer.Resp shortAlias = server.post("/api/links", "{\"url\":\"https://example.com\",\"customAlias\":\"ab\"}");
        assertEquals(400, shortAlias.status());
    }

    @Test
    void honoursIdempotencyKey() {
        String body = "{\"url\":\"https://example.com/i\"}";
        TestServer.Resp a = server.post("/api/links", body, "Idempotency-Key", "order-42");
        TestServer.Resp b = server.post("/api/links", body, "Idempotency-Key", "order-42");
        assertEquals(201, a.status());
        assertEquals(200, b.status());
        assertEquals(server.json(a).get("code"), server.json(b).get("code"));
    }

    @Test
    void deleteSoftDeletesMetadataAndRedirectReturn410StatsStayReadable() {
        String code = server.create("https://example.com/d");
        server.get("/" + code);
        assertEquals(204, server.delete("/api/links/" + code).status());
        assertEquals(410, server.get("/" + code).status());
        assertEquals("GONE", server.json(server.get("/api/links/" + code)).get("error"));
        assertEquals(410, server.delete("/api/links/" + code).status());
        TestServer.Resp stats = server.get("/api/links/" + code + "/stats");
        assertEquals(200, stats.status());
        assertEquals(1, server.json(stats).get("totalClicks"));
    }

    @Test
    void returns404ForUnknownCodes() {
        assertEquals(404, server.get("/zzzzzzz").status());
        assertEquals(404, server.get("/api/links/zzzzzzz").status());
        assertEquals(404, server.get("/api/links/zzzzzzz/stats").status());
        assertEquals("NOT_FOUND", server.json(server.get("/api/links/zzzzzzz")).get("error"));
    }

    @Test
    void exposesHealthProbesMetricsAndTheOpenApiContract() {
        assertEquals("UP", server.json(server.get("/actuator/health/liveness")).get("status"));
        assertEquals("UP", server.json(server.get("/actuator/health/readiness")).get("status"));
        assertEquals(200, server.get("/actuator/metrics/analytics.queue.flushed").status());
        TestServer.Resp spec = server.get("/openapi.yaml");
        assertEquals(200, spec.status());
        assertTrue(spec.body().contains("/api/links/{code}/stats"));
    }

    @Test
    void neverExposesRawInternalsOnUnknownRoutes() {
        TestServer.Resp r = server.get("/api/does-not-exist");
        assertEquals(404, r.status());
        assertNull(server.json(r).get("trace"));
    }
}

package dev.rajeev.shortener.web;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.rajeev.shortener.domain.Link;
import dev.rajeev.shortener.repository.LinkRepository;
import java.time.Instant;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * Acceptance tests for the "links are too easy to guess" fix (written first):
 * generated codes are 8 characters (62^8 ≈ 2.2e14 keyspace), custom aliases must be at least 6
 * characters, and codes that already exist (legacy 7-char generated, 4-char aliases) keep resolving.
 */
class GuessabilityIntegrationTest {

    static TestServer server;

    @BeforeAll
    static void start() {
        server = new TestServer();
    }

    @AfterAll
    static void stop() {
        server.close();
    }

    @Test
    void ac1_generatedCodesAreEightBase62Characters() {
        for (int i = 0; i < 5; i++) {
            TestServer.Resp r = server.post("/api/links", "{\"url\":\"https://example.com/e\"}");
            assertEquals(201, r.status());
            String code = (String) server.json(r).get("code");
            assertTrue(code.matches("^[0-9A-Za-z]{8}$"), code);
        }
    }

    @Test
    void ac2_customAliasesShorterThanSixCharactersAreRejectedWith400() {
        for (String alias : new String[] {"sale", "sale1", "ab-12"}) {
            TestServer.Resp r = server.post("/api/links", "{\"url\":\"https://example.com/a\",\"customAlias\":\"" + alias + "\"}");
            assertEquals(400, r.status(), alias);
        }
        assertEquals(201, server.post("/api/links", "{\"url\":\"https://example.com/a\",\"customAlias\":\"spring-sale\"}").status());
    }

    @Test
    void ac3_existingShortCodesKeepResolving() {
        LinkRepository repo = server.ctx.getBean(LinkRepository.class);
        Instant now = Instant.now();
        repo.insert(new Link("abc1234", "https://example.com/legacy7", now, null, false, null));
        repo.insert(new Link("shop", "https://example.com/legacy4", now, null, true, null));
        assertEquals("https://example.com/legacy7", server.get("/abc1234").header("Location"));
        assertEquals("https://example.com/legacy4", server.get("/shop").header("Location"));
        assertEquals(200, server.get("/api/links/shop/stats").status());
    }
}

package dev.rajeev.shortener.domain;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * Create request. Bean Validation annotations document the contract and fail fast at the edge;
 * {@link LinkService} re-validates explicitly so the rules hold for every caller (not only HTTP).
 */
public record CreateLinkRequest(
        @NotBlank @Size(max = 8192) String url,
        @Pattern(regexp = LinkRules.CUSTOM_ALIAS_REGEX, message = "alias must be 6-32 URL-safe characters") String customAlias,
        @Size(max = 128) String ownerId) {}

package dev.rajeev.shortener.domain;

import java.util.Set;
import java.util.regex.Pattern;

/** Shared validation constants for codes and aliases. */
public final class LinkRules {

    /**
     * Custom aliases at creation time: 6-32 URL-safe characters. The minimum was raised from 4 because
     * short aliases ("sale1") are trivially guessable.
     */
    public static final String CUSTOM_ALIAS_REGEX = "^[A-Za-z0-9_-]{6,32}$";
    public static final Pattern CUSTOM_ALIAS_PATTERN = Pattern.compile(CUSTOM_ALIAS_REGEX);

    /**
     * What a code may look like in a URL path (used by the controllers' path templates). Deliberately
     * wider than the creation rule (4-32) so every code ever issued — legacy 4/5-char aliases, 7-char
     * generated codes — keeps resolving. Tightening this would be a breaking change.
     */
    public static final String CODE_PATH = "[A-Za-z0-9_-]{4,32}";
    public static final Pattern CODE_PATH_PATTERN = Pattern.compile("^" + CODE_PATH + "$");

    /** First path segments a custom alias must never shadow. */
    public static final Set<String> RESERVED_CODES = Set.of("api", "actuator", "health", "ready", "metrics", "docs", "openapi", "error");

    private LinkRules() {}
}

package dev.rajeev.shortener.domain;

import dev.rajeev.shortener.analytics.AnalyticsQueue;
import dev.rajeev.shortener.analytics.ClickEvent;
import dev.rajeev.shortener.analytics.ClickNormalizer;
import dev.rajeev.shortener.repository.AliasTakenException;
import dev.rajeev.shortener.repository.LinkRepository;
import dev.rajeev.shortener.repository.LinkStats;
import java.time.Clock;
import java.util.Locale;

/**
 * Application service: owns the use cases, knows nothing about HTTP. Routes are a thin adapter
 * over this class, which is what makes behaviour testable without a server and what lets the
 * orchestrator's impact analysis point at one module when a rule changes.
 */
public class LinkService {

    public record CreateResult(Link link, boolean created) {}

    private final LinkRepository repo;
    private final CodeGenerator codegen;
    private final AnalyticsQueue analytics;
    private final UrlPolicy urlPolicy;
    private final Clock clock;

    public LinkService(LinkRepository repo, CodeGenerator codegen, AnalyticsQueue analytics, UrlPolicy urlPolicy, Clock clock) {
        this.repo = repo;
        this.codegen = codegen;
        this.analytics = analytics;
        this.urlPolicy = urlPolicy;
        this.clock = clock;
    }

    public CreateResult create(CreateLinkRequest req, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = repo.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) return new CreateResult(existing.get(), false);
        }
        validate(req);

        String normalized = switch (urlPolicy.evaluate(req.url())) {
            case UrlPolicy.Ok ok -> ok.normalized();
            case UrlPolicy.Rejected rejected -> throw new DomainException(rejected.code(), rejected.message());
        };

        String code;
        if (req.customAlias() != null) {
            if (LinkRules.RESERVED_CODES.contains(req.customAlias().toLowerCase(Locale.ROOT))) {
                throw new DomainException(ErrorCode.ALIAS_RESERVED, "'" + req.customAlias() + "' is reserved");
            }
            code = req.customAlias();
        } else {
            try {
                code = codegen.generate(repo::exists);
            } catch (CodeExhaustedException e) {
                throw new DomainException(ErrorCode.CODE_EXHAUSTED, e.getMessage());
            }
        }

        Link link = new Link(code, normalized, clock.instant(), null, req.customAlias() != null, req.ownerId());
        try {
            repo.insert(link);
        } catch (AliasTakenException e) {
            throw new DomainException(ErrorCode.ALIAS_TAKEN, e.getMessage());
        }
        if (idempotencyKey != null && !idempotencyKey.isBlank()) repo.rememberIdempotencyKey(idempotencyKey, code, clock.instant());
        return new CreateResult(link, true);
    }

    /** Explicit validation so the rules hold for every caller, not only for @Valid at the HTTP edge. */
    private static void validate(CreateLinkRequest req) {
        if (req == null || req.url() == null || req.url().isBlank()) throw new DomainException(ErrorCode.VALIDATION, "url is required");
        if (req.url().length() > 8192) throw new DomainException(ErrorCode.VALIDATION, "url is too long");
        if (req.customAlias() != null && !LinkRules.CUSTOM_ALIAS_PATTERN.matcher(req.customAlias()).matches()) {
            throw new DomainException(ErrorCode.VALIDATION, "alias must be 6-32 URL-safe characters");
        }
        if (req.ownerId() != null && req.ownerId().length() > 128) throw new DomainException(ErrorCode.VALIDATION, "ownerId is too long");
    }

    /** Returns the active link or throws NOT_FOUND / GONE. */
    public Link resolve(String code) {
        Link link = repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        if (link.deleted()) throw new DomainException(ErrorCode.GONE, "short link has been deleted");
        return link;
    }

    /** Resolve + fire-and-forget analytics. Redirect latency never waits on the store. */
    public Link resolveAndTrack(String code, String referrer, String userAgent) {
        Link link = resolve(code);
        analytics.enqueue(new ClickEvent(link.code(), clock.instant(), ClickNormalizer.referrer(referrer), ClickNormalizer.userAgent(userAgent)));
        return link;
    }

    public Link get(String code) {
        return resolve(code);
    }

    public void remove(String code) {
        Link link = repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        if (link.deleted()) throw new DomainException(ErrorCode.GONE, "short link has already been deleted");
        repo.softDelete(code, clock.instant());
    }

    public LinkStats stats(String code, int days, int topN) {
        repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        // Stats stay readable after deletion: owners often want the final numbers.
        analytics.flush();
        return repo.stats(code, days, topN);
    }
}

package dev.rajeev.shortener.web;

import dev.rajeev.shortener.config.ShortenerProperties;
import dev.rajeev.shortener.domain.CreateLinkRequest;
import dev.rajeev.shortener.domain.LinkResponse;
import dev.rajeev.shortener.domain.LinkRules;
import dev.rajeev.shortener.domain.LinkService;
import dev.rajeev.shortener.repository.LinkStats;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** Link lifecycle and analytics. Contract: src/main/resources/static/openapi.yaml. */
@RestController
@RequestMapping("/api/links")
public class LinkController {

    private final LinkService service;
    private final String baseUrl;

    public LinkController(LinkService service, ShortenerProperties props) {
        this.service = service;
        this.baseUrl = props.baseUrl();
    }

    /**
     * Create a short link. Send an {@code Idempotency-Key} header to make retries safe: the same key
     * returns the original link with 200 instead of creating a duplicate.
     */
    @PostMapping
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody CreateLinkRequest body,
                                               @RequestHeader(name = "Idempotency-Key", required = false) String idempotencyKey) {
        LinkService.CreateResult result = service.create(body, idempotencyKey);
        return ResponseEntity.status(result.created() ? HttpStatus.CREATED : HttpStatus.OK).body(LinkResponse.from(result.link(), baseUrl));
    }

    @GetMapping("/{code:" + LinkRules.CODE_PATH + "}")
    public LinkResponse get(@PathVariable("code") String code) {
        return LinkResponse.from(service.get(code), baseUrl);
    }

    /** Soft delete: the code is never reissued; stats remain readable. */
    @DeleteMapping("/{code:" + LinkRules.CODE_PATH + "}")
    public ResponseEntity<Void> delete(@PathVariable("code") String code) {
        service.remove(code);
        return ResponseEntity.noContent().build();
    }

    @GetMapping("/{code:" + LinkRules.CODE_PATH + "}/stats")
    public LinkStats stats(@PathVariable("code") String code,
                           @RequestParam(name = "days", defaultValue = "30") int days,
                           @RequestParam(name = "topN", defaultValue = "5") int topN) {
        return service.stats(code, Math.max(1, Math.min(days, 365)), Math.max(1, Math.min(topN, 50)));
    }
}

package dev.rajeev.shortener.web;

import dev.rajeev.shortener.domain.Link;
import dev.rajeev.shortener.domain.LinkRules;
import dev.rajeev.shortener.domain.LinkService;
import java.net.URI;
import org.springframework.http.CacheControl;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

/**
 * GET /{code} -> 302 to the target.
 *
 * 302 (not 301) is deliberate: a 301 is cached aggressively by browsers, which means we would stop
 * seeing clicks after the first visit and a deleted link would keep redirecting from cache.
 * {@code Cache-Control: no-store} reinforces the same intent for intermediaries.
 */
@RestController
public class RedirectController {

    private final LinkService service;

    public RedirectController(LinkService service) {
        this.service = service;
    }

    @GetMapping("/{code:" + LinkRules.CODE_PATH + "}")
    public ResponseEntity<Void> redirect(@PathVariable("code") String code,
                                         @RequestHeader(name = "Referer", required = false) String referer,
                                         @RequestHeader(name = "User-Agent", required = false) String userAgent) {
        Link link = service.resolveAndTrack(code, referer, userAgent);
        return ResponseEntity.status(HttpStatus.FOUND)
                .cacheControl(CacheControl.noStore())
                .location(URI.create(link.targetUrl()))
                .build();
    }
}

package dev.rajeev.shortener.domain;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.rajeev.shortener.analytics.AnalyticsQueue;
import dev.rajeev.shortener.repository.InMemoryLinkRepository;
import dev.rajeev.shortener.repository.LinkStats;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.function.Predicate;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class LinkServiceTest {

    /** Test clock that advances one second per read, so ordering is deterministic. */
    static class TickingClock extends Clock {
        private Instant now = Instant.now().minusSeconds(60);

        @Override public ZoneOffset getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(java.time.ZoneId zone) { return this; }
        @Override public Instant instant() { now = now.plusSeconds(1); return now; }
    }

    static class QueuedCodes implements CodeGenerator {
        final Deque<String> codes = new ArrayDeque<>(List.of("gen0001", "gen0002", "gen0003"));

        @Override
        public String generate(Predicate<String> exists) {
            while (!codes.isEmpty()) {
                String c = codes.pop();
                if (!exists.test(c)) return c;
            }
            throw new IllegalStateException("out of test codes");
        }
    }

    private final InMemoryLinkRepository repo = new InMemoryLinkRepository();
    private final AnalyticsQueue analytics = new AnalyticsQueue(repo, 10_000, 10, 100, 3);
    private final LinkService service = new LinkService(repo, new QueuedCodes(), analytics, new UrlPolicy(2048, List.of("localhost:8080"), false), new TickingClock());

    @AfterEach
    void tearDown() {
        analytics.close();
    }

    private static ErrorCode codeOf(Runnable r) {
        DomainException e = assertThrows(DomainException.class, r::run);
        return e.code();
    }

    @Test
    void createsALinkWithAGeneratedCode() {
        var result = service.create(new CreateLinkRequest("https://example.com", null, null), null);
        assertTrue(result.created());
        assertEquals("gen0001", result.link().code());
        assertEquals("https://example.com/", result.link().targetUrl());
        assertFalse(result.link().custom());
        assertNull(result.link().deletedAt());
    }

    @Test
    void usesACustomAliasWhenGiven() {
        var result = service.create(new CreateLinkRequest("https://example.com", "my-link", "owner-1"), null);
        assertEquals("my-link", result.link().code());
        assertTrue(result.link().custom());
        assertEquals("owner-1", result.link().ownerId());
    }

    @Test
    void rejectsTakenReservedAndInvalidAliases() {
        service.create(new CreateLinkRequest("https://example.com", "taken1", null), null);
        assertEquals(ErrorCode.ALIAS_TAKEN, codeOf(() -> service.create(new CreateLinkRequest("https://other.com", "taken1", null), null)));
        assertEquals(ErrorCode.ALIAS_RESERVED, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", "health", null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", "a b", null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("", null, null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", null, "x".repeat(200)), null)));
    }

    @Test
    void separatesAliasCreationRuleFromPathResolutionRule() {
        assertFalse(LinkRules.CUSTOM_ALIAS_PATTERN.matcher("sale1").matches());
        assertTrue(LinkRules.CUSTOM_ALIAS_PATTERN.matcher("spring-sale").matches());
        assertTrue(LinkRules.CODE_PATH_PATTERN.matcher("sale").matches());
        assertTrue(LinkRules.CODE_PATH_PATTERN.matcher("abc1234").matches());
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", "sale1", null), null)));
    }

    @Test
    void rejectsDisallowedUrlsWithThePolicyReason() {
        assertEquals(ErrorCode.URL_NOT_ALLOWED, codeOf(() -> service.create(new CreateLinkRequest("javascript:alert(1)", null, null), null)));
        assertEquals(ErrorCode.INVALID_URL, codeOf(() -> service.create(new CreateLinkRequest("nope", null, null), null)));
        assertEquals(ErrorCode.URL_NOT_ALLOWED, codeOf(() -> service.create(new CreateLinkRequest("http://localhost:8080/x", null, null), null)));
    }

    @Test
    void isIdempotentOnIdempotencyKey() {
        var a = service.create(new CreateLinkRequest("https://example.com", null, null), "key-1");
        var b = service.create(new CreateLinkRequest("https://example.com", null, null), "key-1");
        assertTrue(a.created());
        assertFalse(b.created());
        assertEquals(a.link().code(), b.link().code());
    }

    @Test
    void mapsCodeExhaustionToCodeExhausted() {
        LinkService exhausted = new LinkService(repo, exists -> { throw new CodeExhaustedException(5); }, analytics, new UrlPolicy(2048, List.of(), false), Clock.systemUTC());
        assertEquals(ErrorCode.CODE_EXHAUSTED, codeOf(() -> exhausted.create(new CreateLinkRequest("https://example.com", null, null), null)));
    }

    @Test
    void resolvesActiveLinksAndTracksClicksAsynchronously() {
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null), null).link();
        Link resolved = service.resolveAndTrack(link.code(), "https://news.ycombinator.com/", "curl/8");
        assertEquals("https://example.com/", resolved.targetUrl());
        assertEquals(1, analytics.metrics().enqueued());
        LinkStats stats = service.stats(link.code(), 30, 5);
        assertEquals(1, stats.totalClicks());
        assertEquals(List.of(new LinkStats.ReferrerCount("news.ycombinator.com", 1)), stats.topReferrers());
        assertEquals(List.of(new LinkStats.UserAgentCount("curl", 1)), stats.topUserAgents());
    }

    @Test
    void returnsNotFoundForUnknownAndGoneForDeleted() {
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.resolve("missing")));
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null), null).link();
        service.remove(link.code());
        assertEquals(ErrorCode.GONE, codeOf(() -> service.resolve(link.code())));
        assertEquals(ErrorCode.GONE, codeOf(() -> service.remove(link.code())));
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.remove("missing")));
    }

    @Test
    void keepsStatsReadableAfterDeletion() {
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null), null).link();
        service.resolveAndTrack(link.code(), null, null);
        service.remove(link.code());
        assertEquals(1, service.stats(link.code(), 30, 5).totalClicks());
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.stats("missing", 30, 5)));
    }
}

package dev.rajeev.shortener.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;

/**
 * Typed configuration bound from {@code shortener.*}. Defaults are the values used in tests;
 * a misconfigured deployment fails at startup (binding), not on the first request.
 */
@ConfigurationProperties(prefix = "shortener")
public record ShortenerProperties(
        @DefaultValue("http://localhost:8080") String baseUrl,
        // 8 chars = 62^8 ≈ 2.2e14 keys. Raised from 7 after users reported links felt guessable; legacy 7-char codes still resolve.
        @DefaultValue("8") int codeLength,
        @DefaultValue("2048") int maxUrlLength,
        @DefaultValue RateLimit rateLimit,
        @DefaultValue Analytics analytics) {

    public record RateLimit(@DefaultValue("100") int max, @DefaultValue("60000") long windowMs) {}

    public record Analytics(
            @DefaultValue("500") long flushIntervalMs,
            @DefaultValue("200") int maxBatch,
            @DefaultValue("10000") int maxQueue,
            @DefaultValue("3") int maxRetries) {}

    public ShortenerProperties {
        if (codeLength < 4 || codeLength > 16) throw new IllegalArgumentException("shortener.code-length must be between 4 and 16");
        if (maxUrlLength < 64) throw new IllegalArgumentException("shortener.max-url-length must be >= 64");
    }
}

package dev.rajeev.shortener.config;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import dev.rajeev.shortener.web.TestServer;
import org.junit.jupiter.api.Test;

class ShortenerPropertiesTest {

    @Test
    void defaultsGeneratedCodeLengthToEightCharacters() {
        try (TestServer server = new TestServer()) {
            assertEquals(8, server.ctx.getBean(ShortenerProperties.class).codeLength());
        }
    }

    @Test
    void stillAllowsAnExplicitOverrideWithinBounds() {
        try (TestServer server = new TestServer("--shortener.code-length=10")) {
            assertEquals(10, server.ctx.getBean(ShortenerProperties.class).codeLength());
        }
        assertThrows(IllegalArgumentException.class, () -> new ShortenerProperties("http://x", 3, 2048, new ShortenerProperties.RateLimit(1, 1000), new ShortenerProperties.Analytics(500, 200, 10000, 3)));
    }
}
